def transform(grid):
    H = len(grid)
    W = len(grid[0])

    min_r = min(r for r in range(H) if any(c != 0 for c in grid[r]))
    max_r = max(r for r in range(H) if any(c != 0 for c in grid[r]))
    min_c = min(c for c in range(W) if any(row[c] != 0 for row in grid))
    max_c = max(c for c in range(W) if any(row[c] != 0 for row in grid))

    result = [[0]*W for _ in range(H)]

    for r in range(min_r, max_r + 1):
        for c in range(min_c, max_c + 1):
            if grid[r][c] == 5:
                result[r][c] = 5
            else:
                dr = r - min_r
                dc = c - min_c
                d = min(dr, dc, (max_r-min_r)-dr, (max_c-min_c)-dc)

                if d == 0:
                    result[r][c] = 5
                elif d == 1:
                    result[r][c] = 2
                elif d == 2:
                    result[r][c] = 5
                else:
                    result[r][c] = 0

    return result

test_input = G['Test input']
test_output = transform(test_input)

